/**
 * Private local-disk storage for files that must never be public (chat
 * images). Files live under PRIVATE_UPLOADS_DIR, which is NOT served by the
 * /media static route; they are only read by services that check access
 * first (messageService.getMessageImage).
 *
 * Keys are generated by the server and checked against a strict pattern, so
 * no path traversal is possible.
 */
const fs = require('fs/promises');
const path = require('path');
const config = require('../../config/environment');

const KEY_PATTERN = /^[a-z0-9-]+\/[a-f0-9-]{36}\.[a-z0-9]{3,4}$/;

function resolveKey(key) {
  if (!KEY_PATTERN.test(key || '')) throw new Error('Invalid storage key');
  const root = config.chatImages.privateDir;
  const file = path.resolve(root, key);
  if (!file.startsWith(root + path.sep)) throw new Error('Invalid storage key');
  return file;
}

async function put(key, buffer) {
  const file = resolveKey(key);
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, buffer, { flag: 'wx' }); // never overwrite
  return { key };
}

/** File contents, or null when it does not exist. */
async function read(key) {
  try {
    return await fs.readFile(resolveKey(key));
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
}

async function remove(key) {
  try {
    await fs.unlink(resolveKey(key));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
}

module.exports = { name: 'private-local', put, read, remove, KEY_PATTERN };
